import { edit_crm_lead_details } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "DragConfirmDialog",
  props: {
    dialog: {
      type: Boolean,
      default: false
    },
    leadName: {
      type: String,
      default: ""
    },
    fromStageName: {
      type: String,
      default: ""
    },
    toStageName: {
      type: String,
      default: ""
    },
    leadData: {
      type: Object,
      default: () => ({})
    }
  },
  data() {
    return {
      loading: false,
      notes: ""
    };
  },
  computed: {
    today() {
      return new Date().toISOString().split("T")[0];
    },
    formattedDeadline: {
      get() {
        if (this.leadData.deadline) {
          let date;
          if (typeof this.leadData.deadline === "number") {
            date = new Date(this.leadData.deadline * 1000);
          } else {
            date = new Date(this.leadData.deadline);
          }
          return date.toISOString().split("T")[0];
        }
        return "";
      },
      set(value) {
        if (value) {
          this.leadData.deadline = new Date(value).getTime() / 1000;
        } else {
          this.leadData.deadline = null;
        }
      }
    }
  },
  methods: {
    async confirm() {
      this.loading = true;
      try {
        // Prepare the input for the mutation
        const input = {
          stage_name: this.toStageName,
          lead_id: this.leadData.lead_id,
          lead_dead_line: this.leadData.deadline,
          comments: this.notes
        };

        // Call the API
        const result = await API.graphql(graphqlOperation(edit_crm_lead_details, {
          input
        }));
        const response = JSON.parse(result.data.edit_crm_lead_details);
        if (response.Status === "SUCCESS") {
          // Emit success message
          this.$emit("successMsg", `Lead moved successfully${this.leadData.deadline ? ` with deadline ${this.leadData.deadline}` : ""}!`);
          this.$emit("confirm", {
            deadline: this.leadData.deadline || null,
            notes: this.notes || null
          });
          this.resetForm();
        } else {
          this.$emit("errorMsg", response.message || "Failed to update lead details.");
        }
      } catch (error) {
        console.error("Error updating lead:", error);
        this.$emit("errorMsg", "Failed to move lead. Please try again.");
      } finally {
        this.loading = false;
      }
    },
    cancel() {
      this.$emit("errorMsg", "Lead movement cancelled.");
      this.$emit("cancel");
      this.resetForm();
    },
    resetForm() {
      this.notes = "";
    }
  },
  watch: {
    dialog(newVal) {
      if (newVal) {
        this.resetForm();
      }
    }
  }
};
